copy (select sp.sample_id::text, max((pd.parameters::jsonb->>'max_temperature')::float) as anneal_maxt from public_release.sample_process sp join public_release.process pr on pr.id=sp.process_id join public_release.process_detail pd on pd.id=pr.process_detail_id where pd.type='anneal' and sp.sample_id=any(string_to_array(:'ids',',')::uuid[]) group by sp.sample_id) to stdout csv header
